import type { RomSlot } from "./rom/romset";

/** Subset of the Emscripten module generated by emulator/build-wasm.sh. */
interface FbneoCoreModule {
  HEAPU8: Uint8Array;
  HEAP16: Int16Array;
  UTF8ToString(ptr: number): string;
  stringToNewUTF8(value: string): number;
  _malloc(size: number): number;
  _free(ptr: number): void;

  _core_init(): number;
  _core_last_error(): number;
  _core_select_driver(namePtr: number): number;
  _core_driver_fullname(): number;
  _core_rom_count(): number;
  _core_rom_name(i: number): number;
  _core_rom_length(i: number): number;
  _core_rom_crc(i: number): number;
  _core_rom_type(i: number): number;
  _core_set_rom(i: number, ptr: number, len: number): number;
  _core_start(sampleRate: number): number;
  _core_width(): number;
  _core_height(): number;
  _core_fps_x100(): number;
  _core_audio_frames_per_video_frame(): number;
  _core_set_input(player: number, buttons: number): void;
  _core_set_system_input(switches: number): void;
  _core_run_frame(render: number): number;
  _core_video_buffer(): number;
  _core_audio_buffer(): number;
  _core_frame_counter(): number;
  _core_reset(): number;
  _core_state_size(): number;
  _core_state_save(ptr: number, len: number): number;
  _core_state_load(ptr: number, len: number): number;
  _core_nvram_size(): number;
  _core_nvram_save(ptr: number, len: number): number;
  _core_nvram_load(ptr: number, len: number): number;
  _core_stop(): void;
}

type CoreFactory = () => Promise<FbneoCoreModule>;

/** FBNeo BRF_OPT: the driver runs without this ROM. */
const BRF_OPT = 1 << 27;

export class EmulatorError extends Error {}

export interface VideoInfo {
  width: number;
  height: number;
  /** Refresh rate in Hz (54.71 for the Midway Wolf-unit). */
  fps: number;
  /** Stereo sample frames produced per emulated frame. */
  audioFramesPerVideoFrame: number;
  sampleRate: number;
}

/**
 * Typed wrapper around the FBNeo WASM core. Owns no timing: every frame is
 * advanced explicitly with runFrame(). Has no DOM dependency so it runs in a
 * Web Worker and in Node (integration tests).
 */
export class EmulatorAdapter {
  private video: VideoInfo | null = null;
  private resetRequested = false;

  private constructor(private readonly core: FbneoCoreModule) {}

  /** `moduleUrl` points to fbneo_core.mjs; the .wasm is resolved next to it. */
  static async load(moduleUrl: string): Promise<EmulatorAdapter> {
    const imported = (await import(/* @vite-ignore */ moduleUrl)) as { default: CoreFactory };
    const core = await imported.default();
    const adapter = new EmulatorAdapter(core);
    adapter.check(core._core_init(), "core_init");
    return adapter;
  }

  get videoInfo(): VideoInfo | null {
    return this.video;
  }

  selectDriver(name: string): { fullName: string; slots: RomSlot[] } {
    const namePtr = this.core.stringToNewUTF8(name);
    try {
      this.check(this.core._core_select_driver(namePtr), "core_select_driver");
    } finally {
      this.core._free(namePtr);
    }

    const slots: RomSlot[] = [];
    const count = this.core._core_rom_count();
    for (let i = 0; i < count; i++) {
      slots.push({
        index: i,
        name: this.core.UTF8ToString(this.core._core_rom_name(i)),
        length: this.core._core_rom_length(i) >>> 0,
        crc: this.core._core_rom_crc(i) >>> 0,
        optional: ((this.core._core_rom_type(i) >>> 0) & BRF_OPT) !== 0,
      });
    }
    return { fullName: this.core.UTF8ToString(this.core._core_driver_fullname()), slots };
  }

  /** Copies the ROM into WASM memory; the core takes ownership of the copy. */
  setRom(index: number, data: Uint8Array): void {
    const ptr = this.core._malloc(data.length);
    if (ptr === 0) {
      throw new EmulatorError(`out of memory copying ROM ${index}`);
    }
    this.core.HEAPU8.set(data, ptr);
    this.check(this.core._core_set_rom(index, ptr, data.length), "core_set_rom");
  }

  start(sampleRate: number): VideoInfo {
    this.check(this.core._core_start(sampleRate), "core_start");
    this.video = {
      width: this.core._core_width(),
      height: this.core._core_height(),
      fps: this.core._core_fps_x100() / 100,
      audioFramesPerVideoFrame: this.core._core_audio_frames_per_video_frame(),
      sampleRate,
    };
    return this.video;
  }

  setInput(player: 0 | 1, buttons: number): void {
    this.core._core_set_input(player, buttons);
  }

  setSystemInput(switches: number): void {
    this.core._core_set_system_input(switches);
  }

  runFrame(render: boolean): void {
    this.check(this.core._core_run_frame(render ? 1 : 0), "core_run_frame");
    this.resetRequested = false;
  }

  get frameCounter(): number {
    return this.core._core_frame_counter() >>> 0;
  }

  /**
   * RGBA8888 view of the last rendered frame. It aliases WASM memory and is
   * only valid until the next call into the core.
   */
  videoFrameView(): Uint8ClampedArray {
    const video = this.requireVideo();
    return new Uint8ClampedArray(this.core.HEAPU8.buffer, this.core._core_video_buffer(), video.width * video.height * 4);
  }

  /** Copy of the interleaved stereo int16 samples of the last frame. */
  audioFrame(): Int16Array {
    const video = this.requireVideo();
    const start = this.core._core_audio_buffer() >> 1;
    return this.core.HEAP16.slice(start, start + video.audioFramesPerVideoFrame * 2);
  }

  /** Requests a hardware reset, applied during the next runFrame(). */
  reset(): void {
    this.check(this.core._core_reset(), "core_reset");
    this.resetRequested = true;
  }

  /**
   * A requested reset lives in the core, outside the save state: two machines
   * with equal states but different pending resets diverge on the next frame.
   */
  get resetPending(): boolean {
    return this.resetRequested;
  }

  saveState(): Uint8Array {
    const size = this.core._core_state_size() >>> 0;
    const ptr = this.core._malloc(size);
    try {
      this.check(this.core._core_state_save(ptr, size), "core_state_save");
      return this.core.HEAPU8.slice(ptr, ptr + size);
    } finally {
      this.core._free(ptr);
    }
  }

  loadState(state: Uint8Array): void {
    const ptr = this.core._malloc(state.length);
    try {
      this.core.HEAPU8.set(state, ptr);
      this.check(this.core._core_state_load(ptr, state.length), "core_state_load");
    } finally {
      this.core._free(ptr);
    }
  }

  /** Copy of the battery-backed RAM (UMK3 CMOS), which survives reset(). */
  nvram(): Uint8Array {
    const size = this.core._core_nvram_size() >>> 0;
    const ptr = this.core._malloc(size);
    try {
      this.check(this.core._core_nvram_save(ptr, size), "core_nvram_save");
      return this.core.HEAPU8.slice(ptr, ptr + size);
    } finally {
      this.core._free(ptr);
    }
  }

  /** Replaces the battery-backed RAM (e.g. with a raw umk3p.fs dump). Call before the game boots. */
  loadNvram(data: Uint8Array): void {
    const ptr = this.core._malloc(data.length);
    try {
      this.core.HEAPU8.set(data, ptr);
      this.check(this.core._core_nvram_load(ptr, data.length), "core_nvram_load");
    } finally {
      this.core._free(ptr);
    }
  }

  stop(): void {
    this.core._core_stop();
    this.video = null;
  }

  private requireVideo(): VideoInfo {
    if (!this.video) {
      throw new EmulatorError("no game running");
    }
    return this.video;
  }

  private check(result: number, call: string): void {
    if (result !== 0) {
      throw new EmulatorError(`${call}: ${this.core.UTF8ToString(this.core._core_last_error())}`);
    }
  }
}
